&lt;h2&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Benefits&lt;/strong&gt;&lt;/span&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Unlimited vacation time with a culture that actively encourages time off&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;401k plan with 3% guaranteed company contribution&lt;/span&gt;&lt;/li&gt;
