&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt; color: rgb(0, 0, 0);&quot;&gt;&lt;strong&gt;Bonus Skills​&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
