&lt;ul&gt;
&lt;li style=&quot;color: rgb(0, 0, 0); font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 10pt;&quot;&gt;Experience developing partner relationships&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0); font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 10pt;&quot;&gt;Specialized expertise in security posture&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0); font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 10pt;&quot;&gt;Experience with self-hosted and SaaS software applications&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0); font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 10pt;&quot;&gt;Hands on experience with DBT&lt;br&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
