&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt; color: rgb(0, 0, 0);&quot;&gt;Bazel, BuildKite, Docker, Kubernetes, Github&lt;/span&gt;&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt; color: rgb(0, 0, 0);&quot;&gt;AWS, GCP, Azure&lt;/span&gt;&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt; color: rgb(0, 0, 0);&quot;&gt;Postgres database&lt;/span&gt;&lt;br&gt;&lt;br&gt;&lt;/li&gt;
