&lt;li style=&quot;color: rgb(0, 0, 0) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Define and own specific program metrics and objectives.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Track and report on PMO KPIs.&lt;br&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
